return $input.all().map(item => {
  const payload = item.json;
  const firstMedia = payload.items?.[0] || {};

  return {
    json: {
      format: payload.format || 'carousel',
      chat_id: payload.chat_id,
      internal_platform_id: payload.internal_platform_id,
      platform_user_id: payload.platform_user_id,
      access_token: payload.access_token,
      file_id: firstMedia.file_id || payload.file_id,
      incoming_type: firstMedia.type || payload.incoming_type || 'photo',
      caption: payload.caption || '',
      items: payload.items || [],
      draft_data: {
        target_platform: 'instagram',
        target_format: payload.format || 'carousel',
        items: payload.items || [],
        caption: payload.caption || ''
      }
    }
  };
});

let platformPostId = null;

// 1. Проверка ветки Reels
try {
  const items = $('[Meta] Publish Reels').all();
  if (items.length > 0 && items[0].json?.id) {
    platformPostId = items[0].json.id;
  }
} catch (e) {
  // Ветка не выполнялась
}

// 2. Проверка ветки Stories
if (!platformPostId) {
  try {
    const items = $('[Meta] Publish Story').all();
    if (items.length > 0 && items[0].json?.id) {
      platformPostId = items[0].json.id;
    }
  } catch (e) {
    // Ветка не выполнялась
  }
}

// 3. Проверка ветки Feed Post
if (!platformPostId) {
  try {
    const items = $('[Meta] Publish Photo Post').all();
    if (items.length > 0 && items[0].json?.id) {
      platformPostId = items[0].json.id;
    }
  } catch (e) {
    // Ветка не выполнялась
  }
}

// 4. Проверка ветки Carousel (резерв под следующий шаг)
if (!platformPostId) {
  try {
    const items = $('[Meta] Publish Carousel').all();
    if (items.length > 0 && items[0].json?.id) {
      platformPostId = items[0].json.id;
    }
  } catch (e) {
    // Ветка не выполнялась
  }
}

// Возврат чистого контракта для родительского сценария
return $input.all().map(() => ({
  json: {
    success: true,
    platform_post_id: platformPostId
  }
}));

return $input.all().map(item => {
  const err = item.json;
  let message = 'Ошибка публикации в Instagram';

  if (err.error?.message) {
    message = err.error.message;
  } else if (err.errorMessage) {
    message = err.errorMessage;
  } else if (err.status_code === 'ERROR') {
    message = 'Серверы Meta отклонили медиафайл (проверьте пропорции 9:16 и битрейт)';
  } else if (err.status_code === 'IN_PROGRESS') {
    message = 'Превышено время ожидания кодирования видео на серверах Meta';
  }

  return {
    json: {
      success: false,
      error_message: message
    }
  };
});

