parameters.jsCode:
return $input.all().map(item => {
  const data = item.json;
  const slides = data.items || data.draft_data?.items || [];

  return {
    json: {
      chat_id: data.chat_id,
      internal_platform_id: data.internal_platform_id,
      platform_user_id: data.platform_user_id,
      access_token: data.access_token,
      items_count: slides.length,
      draft_data: {
        target_platform: 'instagram',
        target_format: 'carousel',
        items: slides,
        caption: data.caption || ''
      }
    }
  };
});

const inputItems = $input.all();
if (!inputItems.length) return [];

const item = inputItems[0].json;
const slides = item.draft_data?.items || [];

return slides.map((slide, index) => ({
  json: {
    file_id: slide.file_id,
    type: slide.type,
    slide_index: index + 1,
    total_slides: slides.length
  }
}));

const items = $input.all();

// Фотографии готовы сразу (status_code отсутствует), видео требует FINISHED
const allFinished = items.every(item => 
  item.json.status_code === 'FINISHED' || !item.json.status_code
);
const hasError = items.some(item => item.json.status_code === 'ERROR');
const finishedCount = items.filter(item => 
  item.json.status_code === 'FINISHED' || !item.json.status_code
).length;

return [{
  json: {
    status: hasError ? 'ERROR' : (allFinished ? 'FINISHED' : 'IN_PROGRESS'),
    allFinished: allFinished,
    finishedCount: finishedCount,
    totalCount: items.length,
    children: items.map(item => item.json.id).join(','),
    childIds: items.map(item => item.json.id)
  }
}];

const items = $input.all();
if (!items.length) return [];

const ids = items[0].json.childIds || [];
return ids.map(id => ({ json: { id } }));
